float isgrid(vec2 coord)
{
    float freq = .2;
    coord += freq/2.;
    if (mod(coord.x,freq) < freq/50.||freq-mod(coord.x,freq) < freq/50.||mod(coord.y,freq) < freq/50.||freq-mod(coord.y,freq) < freq/50.)
    {
        return 1.;
    }
    return 0.2;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float size = .55;
    vec2 uv = (fragCoord * 2. - iResolution.xy) / iResolution.y;
    vec2 pos = vec2(sin(iTime),0.);
    vec2 relativepos = (uv-pos)*(1./size);
    float dist = distance(uv,pos);

    vec3 texturecolor = vec3(isgrid(uv));
    vec3 outcolor = texturecolor;

    if (dist < size) {
        vec2 refractmodifier = (relativepos*(dist-size));
        float lightmodifier = pow(dist*(1./size),16.)/3.;
        vec2 coord = uv+refractmodifier;
        vec3 refractcolor = vec3(isgrid(coord))-lightmodifier;
        outcolor = refractcolor;
    }

    fragColor = vec4(outcolor,1.0);
}
